contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs a Put from this contract to c, then checks the invariant
    // params: lockTime for Put, amount of wei to send
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount); // ensure we can send

        // read observable before-values
        (uint beforeUnlockTime, uint beforeBalance) = (c.Acc(address(this)).unlockTime, c.Acc(address(this)).balance);
        uint beforeContractBal = address(c).balance;

        // perform the Put call and capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlockTime, uint afterBalance) = (c.Acc(address(this)).unlockTime, c.Acc(address(this)).balance);
        uint afterContractBal = address(c).balance;

        // General rule:
        // If Put did not revert then c.Acc[this].balance increased by exactly `amount` (non-decreasing check)
        // and contract's Ether balance increased by exactly `amount`.
        // If Put reverted then both balances remain equal to before-values.
        assert(
            (!reverted && afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount)
            || (reverted && afterBalance == beforeBalance && afterContractBal == beforeContractBal)
        );
    }

    // allow receiving Ether to fund test
    receive() external payable {}
}

