contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    //   am - amount to attempt to collect from c
    // Note: this function is payable only so the test contract can be funded before calling run;
    // the amount sent to this run call is not used in c.Collect (Collect is non-payable) but
    // address(this).balance must be tracked by external funding before the run invocation.
    function run(uint am) public payable {
        // no precondition on am; test must hold for all inputs

        // Read balances before the Collect attempt
        (, uint beforeRecorded) = c.Acc(address(this));
        uint beforeThis = address(this).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        (, uint afterRecorded) = c.Acc(address(this));
        uint afterThis = address(this).balance;

        // General invariant rule:
        // If Collect reverted then nothing observable about balances of c for this address or this contract changed.
        // If Collect succeeded then the recorded balance for this address decreased by exactly am,
        // and this contract's on-chain balance did not decrease (it should increase by at most am).
        // Note: because the recipient is this contract, on success the test contract's balance should increase by am,
        // but to be robust against weird transfer failure semantics we require it did not decrease.
        assert(
            (reverted && afterRecorded == beforeRecorded && afterThis == beforeThis)
            || (!reverted && afterRecorded + am == beforeRecorded && afterThis >= beforeThis)
        );
    }

    // allow receiving Ether (Collect will send Ether to this contract on success)
    receive() external payable {}
}

