contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to Put some value, then try Collect; inputs:
    // putAmount: amount of wei to send to Put
    // lockTime: parameter to Put
    // collectAmount: amount to attempt to Collect
    // For sending ether we require this contract has enough balance.
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount + 1 wei || address(this).balance >= putAmount, "insufficient balance to fund Put");

        // Record c's balance before operations
        uint cBalBefore = address(c).balance;

        // Call Put with Ether putAmount
        // ensure we have the funds
        if (putAmount > 0) {
            // send putAmount to c via Put
            c.Put{value: putAmount}(lockTime);
        } else {
            // zero-value call still allowed
            c.Put{value: 0}(lockTime);
        }

        // after Put, read our holder balance via auto getter: Acc(address) returns (unlockTime,balance) tuple through struct getter
        (uint unlockedAfterPut, uint myBalAfterPut) = c.Acc(address(this));

        // Record contract balance after Put
        uint cBalAfterPut = address(c).balance;

        // Try Collect and capture whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder balance and contract balance after Collect attempt
        (uint unlockedAfterCollect, uint myBalAfterCollect) = c.Acc(address(this));
        uint cBalAfterCollect = address(c).balance;

        // If Collect did not revert then:
        //  - the holder's recorded balance must have decreased by exactly collectAmount
        //  - the contract's ether balance must have decreased by exactly collectAmount
        // We assert that implication as a general rule for all inputs.
        assert(reverted || (myBalAfterPut >= collectAmount && myBalAfterPut - myBalAfterCollect == collectAmount && cBalAfterPut >= collectAmount && cBalAfterPut - cBalAfterCollect == collectAmount));
    }

    // Allow receiving Ether so this test contract can be funded in the harness
    receive() external payable {}
}

