    // Try to show that when Collect succeeds, the holder balance is reduced by the amount collected
    // and the contract's Ether balance decreases accordingly.
    function run(uint putLock, uint putVal, uint collectVal, uint minSum) public payable {
        require(address(this).balance >= putVal, "need funds to put");

        // initialize c: set MinSum and LogFile and mark initialized so subsequent calls behave normally
        // We call these as top-level state-changing calls as required.
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // record balances before Put
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // send Ether to c via Put
        c.Put{value: putVal}(putLock);

        // record balances after Put and before Collect
        uint midHolderBalance = c.Acc(address(this)).balance;
        uint midContractBal = address(c).balance;

        // require that the Put had its expected observable effect: holder balance increased by putVal
        // (This is a precondition on the scenario; if it fails then the later assertion would be unreachable.)
        require(midHolderBalance >= beforeHolderBalance);

        // Attempt Collect and observe whether it reverted
        bool reverted;
        // We cannot call try/catch for external calls that return nothing on older compilers, but solidity ^0.8 supports it.
        try c.Collect(collectVal) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after Collect (if reverted, state shouldn't have changed)
        uint afterHolderBalance = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // If Collect did not revert then holder balance must have decreased by exactly collectVal
        // and the contract's balance must have decreased by at least collectVal.
        // If it reverted then no change in holder balance or contract balance is required by this property.
        assert(
            reverted ? (afterHolderBalance == midHolderBalance && afterContractBal == midContractBal)
                     : (midHolderBalance >= collectVal &&
                        afterHolderBalance + collectVal == midHolderBalance &&
                        midContractBal >= afterContractBal &&
                        midContractBal - afterContractBal >= collectVal)
        );
    }

    // allow receiving refunds if needed
    receive() external payable {}
}

