    // params: amount to Put, lock time for Put, amount to attempt to Collect, minSum and log address for initialization
    function run(uint putAmt, uint putLock, uint collectAmt, uint minSum, address logAddr) public payable {
        // ensure this test contract has enough ETH to send putAmt when calling Put
        require(address(this).balance >= putAmt, "insufficient balance for Put");

        // initialize C so behavior is deterministic
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // read recorded holder info and contract balance before interactions
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        // perform Put to deposit funds into c (may revert)
        bool putReverted;
        try c.Put{value: putAmt}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read recorded holder info and contract balance after Put and before Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // attempt Collect of collectAmt (may revert)
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General invariant: If Collect succeeded then the drop in stored Acc balance equals the drop in address(c).balance.
        // If Collect reverted then both remained unchanged from immediately before Collect.
        assert((!collectReverted && midBal >= afterBal && midCbal >= afterCbal && (midBal - afterBal) == (midCbal - afterCbal))
             || (collectReverted && afterBal == midBal && afterCbal == midCbal));
    }

    // allow receiving Ether so Collect's transfer to this contract can succeed
    receive() external payable {}
}
